-- Generated by scripts/schema-snapshot.mjs from project heuhqqoxyggawuckxocp. Do not edit by hand.

-- SECURITY DEFINER; API roles that may call it: authenticated, service_role
CREATE OR REPLACE FUNCTION public.milestone_standings()
 RETURNS TABLE(id uuid, name text, photo_url text, reached integer, latest_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select p.id, p.name, p.photo_url,
         coalesce(k.n, 0)::int as reached,
         (select max(cm.reached_at) from public.creator_milestones cm where cm.profile_id = p.id) as latest_at
  from public.profiles p
  cross join lateral (
    select count(*) as n from public.milestone_state(p.id) g where g.reached
  ) k
  where p.status = 'active'
    and p.is_test = false
    -- ADMINS ARE NEVER ON THE ROUTE. The ladder measures creator work, and an
    -- admin account posts nothing, refers nobody and would sit permanently at
    -- the first dot telling every creator that the team is behind them.
    and p.is_admin = false
    and coalesce(p.is_sandbox, false) = false
    and p.deletion_requested_at is null
  order by reached desc, latest_at asc nulls last, p.name;
$function$;
